         )

mapper.select:
SELECT id, name, no, gender, phone, degree, id_card as idCard, is_college as isCollege, address, graduation_date as graduationDate, violation_count as violationCount, violation_score as violationScore, clazz_id as clazzId, create_time as createTime, update_time as updateTime FROM student
AND name LIKE CONCAT('%', #{name}, '%')
AND no LIKE CONCAT('%', #{no}, '%')
AND degree = #{degree}
AND clazz_id = #{clazzId}
ORDER BY create_time DESC
